params.content:
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f4f4f4;
}

header {
    background-color: #333;
    color: #fff;
    padding: 1rem 0;
    text-align: center;
}

header .logo img {
    max-width: 150px;
}

nav ul {
    list-style: none;
    padding: 0;
}

nav ul li {
    display: inline;
    margin: 0 1rem;
}

nav ul li a {
    color: #fff;
    text-decoration: none;
    font-weight: bold;
}

.hero {
    background: url('images/hero.jpg') no-repeat center center/cover;
    color: #fff;
    text-align: center;
    padding: 5rem 1rem;
}

.hero h1 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.hero p {
    font-size: 1.2rem;
    margin-bottom: 2rem;
}

.hero .btn {
    background-color: #fff;
    color: #333;
    padding: 0.5rem 1.5rem;
    text-decoration: none;
    border-radius: 5px;
    transition: background-color 0.3s;
}

.hero .btn:hover {
    background-color: #333;
    color: #fff;
}

.articles {
    display: flex;
    justify-content: space-around;
    flex-wrap: wrap;
    padding: 2rem 1rem;
}

.articles article {
    background-color: #fff;
    border: 1px solid #ddd;
    border-radius: 5px;
    padding: 1rem;
    margin: 1rem;
    max-width: 300px;
}

.articles article img {
    max-width: 100%;
    height: auto;
}

.articles article h2 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
}

.articles article p {
    font-size: 1rem;
    margin-bottom: 1rem;
}

.articles article .btn {
    background-color: #333;
    color: #fff;
    padding: 0.5rem 1.5rem;
    text-decoration: none;
    border-radius: 5px;
    transition: background-color 0.3s;
}

.articles article .btn:hover {
    background-color: #fff;
    color: #333;
}

.subscribe {
    background-color: #333;
    color: #fff;
    padding: 2rem 1rem;
    text-align: center;
}

.subscribe h2 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.subscribe form {
    display: flex;
    justify-content: center;
    align-items: center;
}

.subscribe form label {
    margin-right: 0.5rem;
}

.subscribe form input[type="email"] {
    padding: 0.5rem;
    border: 1px solid #ddd;
    border-radius: 5px;
    margin-right: 0.5rem;
}

.subscribe form .btn {
    background-color: #fff;
    color: #333;
    padding: 0.5rem 1.5rem;
    text-decoration: none;
    border-radius: 5px;
    transition: background-color 0.3s;
}

.subscribe form .btn:hover {
    background-color: #333;
    color: #fff;
}

footer {
    background-color: #333;
    color: #fff;
    text-align: center;
    padding: 1rem 0;
}

a {
    color: #333;
}

a:hover {
    color: #fff;
}

document.addEventListener('DOMContentLoaded', function() {
    const subscribeForm = document.getElementById('subscribeForm');

    subscribeForm.addEventListener('submit', function(event) {
        event.preventDefault();

        const email = document.getElementById('email').value;

        if (email) {
            alert('Thank you for subscribing!');
            subscribeForm.reset();
        } else {
            alert('Please enter a valid email address.');
        }
    });
});
